<script setup lang="ts">
import {computed,ref,onBeforeUnmount,watch,onMounted} from 'vue'
import {modelFieldError} from '@/lib/personalAiModel'
import {request} from '@/api/client'
import type {PersonalAiSetting} from '@/types/personal'
const emit=defineEmits<{ 'select-model': [model: string] }>()
const props=defineProps<{setting:PersonalAiSetting;disabled:boolean}>(),busy=ref(false),error=ref(''),approved=ref(false)
const modelProblem=computed(()=>modelFieldError(props.setting.provider,props.setting.model))
function selectModel(model:string){if(!busy.value&&!props.disabled&&result.value?.success&&result.value.models.includes(model))emit('select-model',model)}
const preview=ref<{token:string;request:string;endpoint:string;model:string}>(),result=ref<{success:boolean;code:string;message:string;milliseconds:number;models:string[];inputTokens:number|null;outputTokens:number|null;usageStatus:string}>()
let active=true,epoch=0;onBeforeUnmount(()=>{active=false;epoch++});watch(()=>props.setting.revision,()=>{epoch++;preview.value=undefined;result.value=undefined;approved.value=false;busy.value=false})
async function prepare(mode:string){if(busy.value||props.disabled||(mode!=='MODELS'&&modelProblem.value))return;const version=++epoch;busy.value=true;error.value='';result.value=undefined;approved.value=false;try{const p=await request<typeof preview.value>(`/personal-ai/settings/${props.setting.provider}/diagnostics/preview`,{method:'POST',body:JSON.stringify({mode})});if(active&&version===epoch)preview.value=p}catch(e){if(active&&version===epoch)error.value=(e as Error).message}finally{if(active&&version===epoch)busy.value=false}}
async function execute(){if(!preview.value||!approved.value||busy.value||props.disabled)return;const version=epoch,token=preview.value.token;busy.value=true;error.value='';preview.value=undefined;try{const r=await request<typeof result.value>('/personal-ai/settings/diagnostics/execute',{method:'POST',body:JSON.stringify({token,confirmed:true})});if(active&&version===epoch){result.value=r;void loadChecks()} }catch(e){if(active&&version===epoch)error.value=(e as Error).message}finally{if(active&&version===epoch)busy.value=false}}
const checks=ref<{mode:string;success:boolean;code:string;checkedAt:string}[]>([])
async function loadChecks(){const version=epoch;try{const data=await request<typeof checks.value>(`/personal-ai/settings/${props.setting.provider}/diagnostics`);if(active&&version===epoch)checks.value=Array.isArray(data)?data:[]}catch{}}
onMounted(loadChecks);watch(()=>[props.setting.provider,props.setting.revision],()=>{checks.value=[];void loadChecks()})
const checkLabels:Record<string,string>={MODELS:'鉴权与目录',CONNECTION:'文字生成',VISION:'图片理解'}
</script>
<template><section class="ai-diagnostics"><h4>检查已保存的配置</h4><div class="check-statuses"><span v-for="(label,key) in checkLabels" :key="key">{{label}} · {{checks.find(c=>c.mode===key)?.success ? '已验证' : checks.some(c=>c.mode===key) ? '未通过' : '未验证'}}</span></div><p>模型目录和连接测试分别检查。发送前会显示请求内容；不会携带个人记忆、笔记或文件。</p><div><button type="button" class="button button--ghost button--small" :disabled="busy||disabled||!setting.configured||!setting.enabled" @click="prepare('MODELS')">查询模型目录</button><button type="button" class="button button--ghost button--small" :disabled="busy||disabled||!setting.configured||!setting.enabled||!!modelProblem" @click="prepare('CONNECTION')">测试当前模型</button><button type="button" class="button button--ghost button--small" :disabled="busy||disabled||!setting.configured||!setting.enabled||!!modelProblem" @click="prepare('VISION')">验证图片理解</button></div><p v-if="modelProblem" class="model-help" role="status">{{modelProblem}} 查询目录不需要先填正确的模型名称。</p><p v-if="busy" role="status">正在检查…</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div v-if="preview" class="diagnostic-preview"><strong>{{preview.model}}</strong><code>{{preview.endpoint}}</code><p>{{preview.request}}</p><label><input v-model="approved" type="checkbox" />我确认发送这个检查请求</label><button type="button" class="button button--dark button--small" :disabled="!approved||busy||disabled" @click="execute">确认检查</button><button type="button" class="table-action" :disabled="busy" @click="preview=undefined">取消</button></div><div v-if="result" class="diagnostic-result" :class="{'form-error':!result.success}" role="status"><p>{{result.message}} · {{result.milliseconds}} ms</p><p v-if="result.inputTokens!=null">输入 {{result.inputTokens}} / 输出 {{result.outputTokens??'未返回'}} tokens</p><p v-if="result.usageStatus==='NOT_SENT'">请求在发送前已停止，未调用供应商模型。</p><p v-if="result.usageStatus==='UNCONFIRMED'">使用记录保存情况未确认，请查看供应商账单。</p><details v-if="result.models.length" open><summary>模型目录 · {{result.models.length}}</summary><p>选择后会填入上方模型栏；保存配置后生效，不会自动调用模型。</p><ul class="model-list"><li v-for="model in result.models" :key="model"><code>{{model}}</code><button type="button" class="button button--ghost button--small" :aria-label="`使用模型 ${model}`" :disabled="busy||disabled||model===setting.model" @click="selectModel(model)">{{model===setting.model ? '当前模型' : '使用此模型'}}</button></li></ul></details></div></section></template>
<style scoped>.ai-diagnostics{border-top:1px solid var(--line);padding:24px 0;margin-top:24px}p{font-size:13px;line-height:1.8;color:var(--muted)}.ai-diagnostics>div{display:flex;gap:12px;flex-wrap:wrap}.diagnostic-result{display:block!important;margin-top:16px}.diagnostic-result p{margin:0}.diagnostic-preview{display:grid!important;padding:20px;border:1px solid var(--line);margin-top:20px}code{overflow-wrap:anywhere}ul{max-height:240px;overflow:auto;padding-left:20px}.model-help{padding:12px 16px;border-left:2px solid var(--green);background:var(--surface-soft,transparent)}.model-list{list-style:none;padding:0;max-height:280px}.model-list li{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--line)}.model-list button{flex-shrink:0}summary{cursor:pointer;color:var(--green)}</style>
